contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    // single public test function: depositAmount is the ETH to deposit into c
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        // ensure this test contract holds enough ETH to deposit
        require(address(this).balance >= depositAmount);
        // record c balance before any action
        uint beforeC = address(c).balance;
        // make a deposit into c
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;
        // attempt first withdrawAll and record whether it reverted
        bool firstReverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }
        // record c balance after first withdraw attempt
        uint afterFirst = address(c).balance;
        // attempt second withdrawAll and record whether it reverted
        bool secondReverted;
        c.withdrawAll(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }
        // record c balance after second withdraw attempt
        uint afterSecond = address(c).balance;
        // General rule: if the first withdraw did not revert then the second withdraw must not be able
        // to decrease c's balance further (i.e., afterSecond >= afterFirst). This captures that the
        // recorded credit for this caller was cleared by the successful first withdraw.
        assert(firstReverted || afterSecond >= afterFirst);
    }
    receive() external payable { }
}

